import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 95 Tickets, please.","description":"学习 had better 与时间表达，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 95 Tickets, please.","description":"学习 had better 与时间表达，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 had better 与时间表达，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 94 When did you or will you go ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-094"},"next":{"text":"第一册：英语初阶 · Lesson 96 What's the exact time?","link":"/life/english/new-concept/book-1/unit-04/lesson-096"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 94 When did you or will you go ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-094"},"next":{"text":"第一册：英语初阶 · Lesson 96 What's the exact time?","link":"/life/english/new-concept/book-1/unit-04/lesson-096"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/lesson-095.md","filePath":"life/english/new-concept/book-1/unit-04/lesson-095.md"}`),r={name:"life/english/new-concept/book-1/unit-04/lesson-095.md"};function i(l,e,s,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-95-tickets-please" tabindex="-1">第一册：英语初阶 · Lesson 95 Tickets, please. <a class="header-anchor" href="#第一册-英语初阶-·-lesson-95-tickets-please" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 95 Tickets, please.&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元 4</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-096">配套课 Lesson 96</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>询问准确时间并作出建议 本课要掌握had better 与时间表达，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>ticket</td><td>/ˈtɪkɪt/</td><td>n.</td><td>票</td><td>a return ticket</td></tr><tr><td>platform</td><td>/ˈplætfɔːm/</td><td>n.</td><td>站台</td><td>platform three</td></tr><tr><td>exact</td><td>/ɪɡˈzækt/</td><td>adj.</td><td>准确的</td><td>the exact time</td></tr><tr><td>depart</td><td>/dɪˈpɑːt/</td><td>v.</td><td>出发</td><td>depart at noon</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>had better leave — 最好现在出发</li><li>had better not wait — 最好不要等</li></ul><h2 id="语法讲解-had-better-与时间表达" tabindex="-1">语法讲解：had better 与时间表达 <a class="header-anchor" href="#语法讲解-had-better-与时间表达" aria-label="Permalink to &quot;语法讲解：had better 与时间表达&quot;">​</a></h2><p>had better + 动词原形表示在当前情境下最好做某事，常带不这样做会有后果的意味。虽然含 had，整体不表示过去；否定为 had better not + 原形。时间可用直接读法 ten twenty，或 twenty past ten。问确切发车时间时要明确日期与上午下午，避免只说含糊钟点。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We had better leave before the traffic gets heavy.</p></blockquote><p>我们最好在交通拥堵前出发。</p><p>Had better 后直接接 leave，表示当前建议；before the traffic gets heavy 是时间从句，用现在时表达将来。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>had better 后不加 to；否定 not 放在 better 后，而不是用 don&#39;t。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“We had better leave before the traffic gets heavy.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We had better leave before the traffic gets heavy. You had better not miss the last train.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“询问准确时间并作出建议”写两至三句，再读给同伴听。至少使用一次had better 与时间表达，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Had better 后直接接 leave，表示当前建议；before the traffic gets heavy 是时间从句，用现在时表达将来。 Had better not 加 miss 表否定建议；the last train 为宾语，had better 不是过去发生的动作。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补原形：We had better ___ (leave) now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> leave</p><p><strong>解析：</strong> 按本课规则判断：had better + 动词原形表示在当前情境下最好做某事，常带不这样做会有后果的意味。虽然含 had，整体不表示过去；否定为 had better not + 原形。时间可用直接读法 ten twenty，或 twenty past ten。问确切发车时间时要明确日期与上午下午，避免只说含糊钟点。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我们最好在交通拥堵前出发。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We had better leave before the traffic gets heavy.</p><p><strong>解析：</strong> Had better 后直接接 leave，表示当前建议；before the traffic gets heavy 是时间从句，用现在时表达将来。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：You had better not miss the last train.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 你最好不要错过末班车。</p><p><strong>解析：</strong> Had better not 加 miss 表否定建议；the last train 为宾语，had better 不是过去发生的动作。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：had better 与时间表达。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-094">上一课</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-096">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=t(r,[["render",i]]);export{b as __pageData,u as default};
